#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

std::ostream& operator<<(std::ostream& destino, const Recuento& valor) {
    return destino << '[' << valor.aceptados << ';' << valor.rechazados << ']';
}

std::istream& operator>>(std::istream& origen, Recuento& destino) {
    char abre{0};
    char separador{0};
    char cierra{0};
    int aceptados{0};
    int rechazados{0};
    if (!(origen >> abre >> aceptados >> separador >> rechazados >> cierra)) {
        return origen;
    }
    Recuento candidato{aceptados, rechazados};
    if (abre != '[' || separador != ';' || cierra != ']' || !recuento_valido(candidato)) {
        origen.setstate(std::ios::failbit);
        return origen;
    }
    destino = candidato;
    return origen;
}

void probar(const std::string& datos) {
    std::istringstream entrada{datos};
    Recuento destino{6, 2};
    if (entrada >> destino) { std::cout << "OK " << destino << "\n"; }
    else { std::cout << "Échec " << destino << "\n"; }
}

int main() {
    const std::vector<std::string> casos{
        "[2;1]", "[0;0]", "[10;10]", "[-1;2]", "[11;0]",
        "[0;-1]", "[0;11]", "[2:1]", "[2;1", "[ 1 ; 3 ]", "[2;1]reste"
    };
    for (const std::string& datos : casos) { probar(datos); }
    return 0;
}
